package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Emulator CI only: private database and injected screen events; no actual Usage Access or outputs. */
public class MissedNightFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private MissedNightActivity activity;
    private static final long NOW=Instant.parse("2026-10-23T12:00:00Z").toEpochMilli(),START=Instant.parse("2026-10-22T22:00:00Z").toEpochMilli(),END=Instant.parse("2026-10-23T06:30:00Z").toEpochMilli();
    private static final class Usage implements MissedNightUsagePort {
        volatile boolean allowed,fail,block,acceptRevoked;volatile int settings,queries;volatile List<MissedNight.Event> events=List.of(new MissedNight.Event(START,MissedNight.Kind.OFF),new MissedNight.Event(END,MissedNight.Kind.ON));final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
        public boolean allowed(){return allowed;}
        public List<MissedNight.Event> query(long from,long to){queries++;if(block){entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IllegalStateException("Fixture save gate timed out.");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}}if(fail)throw new IllegalStateException("Fixture phone-activity query unavailable.");if(!allowed&&!acceptRevoked)throw new SecurityException("Fixture Usage Access off.");return events;}
        public void settings(Activity activity){settings++;allowed=true;}
    }
    private void guard()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));}
    private UiObject2 object(String desc)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(desc)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(desc,scroll.exists());scroll.scrollIntoView(new UiSelector().description(desc));found=device.wait(Until.findObject(By.desc(desc)),3000);}assertNotNull(desc,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),3000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(text,scroll.exists());scroll.scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void launch(String title)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MissedNightActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,MissedNightActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Phone-event fixture · no sensor measurements").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(MissedNightActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(title,device.wait(Until.hasObject(By.text(title)),5000));}
    private void recreate(String title)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(MissedNightActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(MissedNightActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(title,device.wait(Until.hasObject(By.text(title)),5000));}
    private void finish()throws Exception{MissedNightActivity closing=activity;i.runOnMainSync(closing::finish);long until=SystemClock.elapsedRealtime()+5000;while(!closing.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(closing.isDestroyed());closing.awaitReaders(5000);}
    private void settingsOpened(Usage usage){int[] calls={0};long until=SystemClock.elapsedRealtime()+5000;do{i.runOnMainSync(()->calls[0]=usage.settings);if(calls[0]==0)SystemClock.sleep(25);}while(calls[0]==0&&SystemClock.elapsedRealtime()<until);assertEquals("The settings action must reach the pinned Usage Access port",1,calls[0]);}
    private void capture(String suffix)throws Exception{long until=SystemClock.elapsedRealtime()+5000;CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused missing-night window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"missed-night-"+suffix+".png")));}
    @Test public void reviewEditSaveRecreateAndMissingEvidenceStatesUseOnlyPrivateData()throws Exception{
        guard();String name="missing-night-"+UUID.randomUUID()+".db";Records.Factory oldRecords=Records.factory;MissedNightUsage.Factory oldUsage=MissedNightUsage.factory;java.util.function.LongSupplier oldClock=MissedNightActivity.clock;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());Usage usage=new Usage(),revoked=new Usage();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue("Only inert review activity is allowed",a instanceof MissedNightActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        Alarm alarm=new Alarm(9);alarm.enabled=false;alarm.label="Unchanged fixture alarm";String originalAlarm=alarm.json().toString();
        try{
            try(Store store=new Store(c,name)){store.save(alarm);}i.runOnMainSync(()->{Records.factory=context->new Store(context,name);MissedNightUsage.factory=context->usage;MissedNightActivity.clock=()->NOW;});
            launch("Allow phone activity access");assertEquals(0,usage.queries);capture("denied");click("Open Usage Access");settingsOpened(usage);recreate("Phone-idle estimate");capture("review");try(Store store=new Store(c,name)){assertTrue(store.rows("SELECT id FROM sessions").isEmpty());}
            object("Start").click();assertTrue(device.wait(Until.hasObject(By.desc("Options for Start date")),3000));click("Cancel");assertTrue(device.wait(Until.gone(By.desc("Options for Start date")),3000));
            object("End").click();String endDate=Instant.ofEpochMilli(END).atZone(ZoneId.systemDefault()).toLocalDate().format(DateTimeFormatter.ofPattern("EEE d MMM uuuu",Locale.getDefault()));object(endDate).click();assertTrue(device.wait(Until.hasObject(By.text("End time")),3000));object("Minute").setText("45");recreate("End time");assertEquals("45",object("Minute").getText());click("Use time");assertTrue(device.wait(Until.gone(By.text("End time")),3000));String editedClock=RecordUi.clock(c,END+15*60000L,ZoneId.systemDefault());assertTrue(device.wait(Until.hasObject(By.text(editedClock)),3000));capture("edited");recreate("Phone-idle estimate");assertTrue(device.hasObject(By.text(editedClock)));try(Store store=new Store(c,name)){assertTrue(store.rows("SELECT id FROM sessions").isEmpty());}capture("recreated");
            usage.block=true;i.runOnMainSync(()->Records.factory=context->{throw new AssertionError("Save must use the pinned private factory");});click("Save reviewed night");assertTrue(usage.entered.await(3,TimeUnit.SECONDS));capture("busy");recreate("Saving…");usage.block=false;usage.release.countDown();assertTrue(device.wait(Until.hasObject(By.text("Saved to history")),5000));capture("saved");
            try(Store store=new Store(c,name)){List<RecordEntry> entries=Records.all(store);assertEquals(1,entries.size());RecordEntry record=entries.get(0);assertTrue(record.manual());assertEquals(START,record.edit.start);assertEquals(END+15*60000L,record.edit.end);assertEquals(List.of("Phone-idle estimate"),record.edit.tags);assertTrue(record.edit.note.contains("does not prove sleep"));for(String table:new String[]{"epochs","clips","sound_events"})assertTrue(table,store.rows("SELECT * FROM "+table).isEmpty());assertEquals(originalAlarm,store.alarm(9).json().toString());}
            finish();i.runOnMainSync(()->Records.factory=context->new Store(context,name));launch("This night is already recorded");capture("covered");finish();
            revoked.allowed=true;revoked.block=true;revoked.acceptRevoked=true;i.runOnMainSync(()->MissedNightUsage.factory=context->revoked);launch("Checking this night…");assertTrue(revoked.entered.await(3,TimeUnit.SECONDS));revoked.allowed=false;i.runOnMainSync(()->{i.callActivityOnPause(activity);i.callActivityOnResume(activity);});assertTrue(device.wait(Until.hasObject(By.text("Allow phone activity access")),3000));revoked.block=false;revoked.release.countDown();activity.awaitReaders(5000);i.waitForIdleSync();assertTrue(device.hasObject(By.text("Allow phone activity access")));assertFalse(device.hasObject(By.text("This night is already recorded")));finish();i.runOnMainSync(()->MissedNightUsage.factory=context->usage);
            try(Store store=new Store(c,name)){store.getWritableDatabase().delete("record_create_requests",null,null);store.getWritableDatabase().delete("record_edits",null,null);store.getWritableDatabase().delete("sessions",null,null);}usage.events=List.of(new MissedNight.Event(START,MissedNight.Kind.OFF));launch("No complete inactive period");capture("incomplete");finish();usage.events=List.of();launch("No phone activity available");capture("empty");finish();usage.fail=true;launch("Phone activity unavailable");assertTrue(device.hasObject(By.text("Fixture phone-activity query unavailable.")));capture("error");finish();
            usage.fail=false;usage.events=List.of(new MissedNight.Event(START,MissedNight.Kind.OFF),new MissedNight.Event(END,MissedNight.Kind.ON));launch("Phone-idle estimate");try(Store store=new Store(c,name)){Records.create(store,new RecordDraft(START+60000,END-60000),ZoneOffset.UTC,NOW);}click("Save reviewed night");assertTrue(device.wait(Until.hasObject(By.text("A sleep record now overlaps this estimate. Check your history before saving.")),5000));capture("conflict");try(Store store=new Store(c,name)){assertEquals(1,store.rows("SELECT id FROM sessions").size());assertEquals(originalAlarm,store.alarm(9).json().toString());}assertEquals(prefs,Prefs.of(c).getAll());guard();
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"missed-night-failure.png"));device.dumpWindowHierarchy(new File(folder,"missed-night-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{usage.release.countDown();revoked.release.countDown();try{PlanOperations.drain(10000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();for(Activity a:owned)((MissedNightActivity)a).awaitReaders(5000);long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=oldRecords;MissedNightUsage.factory=oldUsage;MissedNightActivity.clock=oldClock;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);}}
    }
    @Test public void manualSaveIsIdempotentAndRechecksDeletedRequestsOpenRecordsAndChangedEvidence()throws Exception{
        guard();String name="missing-night-storage-"+UUID.randomUUID()+".db";Usage usage=new Usage();usage.allowed=true;MissedNight.Interval evidence=new MissedNight.Interval(START,END);long from=START-6*3600000L,to=END+3600000L;
        try(Store store=new Store(c,name)){
            long id=MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"request");int queries=usage.queries;usage.allowed=false;usage.fail=true;assertEquals(id,MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"request"));assertEquals(queries,usage.queries);assertEquals(1,Records.all(store).size());
            Records.delete(store,id,Records.get(store,id).updated);assertThrows(IllegalArgumentException.class,()->MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"request"));assertTrue(Records.all(store).isEmpty());usage.allowed=true;usage.fail=false;
            usage.events=List.of(new MissedNight.Event(START,MissedNight.Kind.OFF),new MissedNight.Event(END-60000,MissedNight.Kind.ON));assertThrows(IllegalArgumentException.class,()->MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"changed"));assertTrue(Records.all(store).isEmpty());
            usage.events=List.of(new MissedNight.Event(START,MissedNight.Kind.OFF),new MissedNight.Event(END,MissedNight.Kind.ON));ContentValues open=new ContentValues();open.put("start",START+60000);store.getWritableDatabase().insertOrThrow("sessions",null,open);assertThrows(IllegalArgumentException.class,()->MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"open-overlap"));assertEquals(1,store.rows("SELECT id FROM sessions").size());assertTrue(store.rows("SELECT * FROM record_edits").isEmpty());
            store.getWritableDatabase().delete("sessions",null,null);ContentValues empty=new ContentValues();empty.put("start",START-7200000);long emptyId=store.getWritableDatabase().insertOrThrow("sessions",null,empty);store.recoverInterrupted();ContentValues reversed=new ContentValues();reversed.put("start",START-3600000);reversed.put("end",START-3600001);long reversedId=store.getWritableDatabase().insertOrThrow("sessions",null,reversed);String untouched=store.rows("SELECT id,start,end FROM sessions ORDER BY id").toString();assertTrue(MissedNightRecords.occupied(store).isEmpty());assertTrue(MissedNightRecords.save(store,usage,evidence,new RecordDraft(START,END),ZoneOffset.UTC,from,to,NOW,"empty-legacy")>0);assertEquals(3,store.rows("SELECT id FROM sessions").size());assertEquals(untouched,store.rows("SELECT id,start,end FROM sessions WHERE id IN (?,?) ORDER BY id",""+emptyId,""+reversedId).toString());
        }finally{c.deleteDatabase(name);}guard();
    }
}
